def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    seeds = [(y, x) for y in range(H) for x in range(W) if g[y, x] != bg]
    for (y, x) in seeds:
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                yy, xx = y + dy, x + dx
                if (dy or dx) and 0 <= yy < H and 0 <= xx < W and g[yy, xx] == bg:
                    out[yy, xx] = 1
        emit(out, f"Stamp a blue 3x3 ring around the grey cell at ({y},{x}).")
    emit(out, "All grey cells are now framed by blue rings; final grid.")
    return out
